-- LoL 5v5 customs: a signup card in Discord, teams generated by lol-amis. lol-amis owns players,
-- links (person.discord_id) and ratings; these tables only hold the evening's own state.

CREATE TABLE IF NOT EXISTS customs_config (
    guild_id    BIGINT PRIMARY KEY,
    channel_id  BIGINT NOT NULL,
    role_id     BIGINT
);

CREATE TABLE IF NOT EXISTS customs (
    id            BIGSERIAL PRIMARY KEY,
    guild_id      BIGINT NOT NULL,
    organiser_id  BIGINT NOT NULL,
    channel_id    BIGINT NOT NULL,
    message_id    BIGINT,
    mode          TEXT NOT NULL CHECK (mode IN ('fixed', 'vote')),
    start_at      TIMESTAMPTZ,
    status        TEXT NOT NULL DEFAULT 'signup' CHECK (status IN ('signup', 'teams', 'done', 'cancelled')),
    reminded_at   TIMESTAMPTZ,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- One open custom per guild, enforced by the database rather than by a check-then-insert.
CREATE UNIQUE INDEX IF NOT EXISTS customs_one_open_per_guild
    ON customs (guild_id) WHERE status IN ('signup', 'teams');

CREATE TABLE IF NOT EXISTS custom_slots (
    custom_id  BIGINT NOT NULL REFERENCES customs (id) ON DELETE CASCADE,
    slot_at    TIMESTAMPTZ NOT NULL,
    PRIMARY KEY (custom_id, slot_at)
);

CREATE TABLE IF NOT EXISTS custom_votes (
    custom_id  BIGINT NOT NULL REFERENCES customs (id) ON DELETE CASCADE,
    slot_at    TIMESTAMPTZ NOT NULL,
    user_id    BIGINT NOT NULL,
    voted_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (custom_id, slot_at, user_id)
);

-- user_id NULL = a guest without Discord, added by the organiser. Order = signup order; the
-- first ten play, the rest wait.
CREATE TABLE IF NOT EXISTS custom_signups (
    id          BIGSERIAL PRIMARY KEY,
    custom_id   BIGINT NOT NULL REFERENCES customs (id) ON DELETE CASCADE,
    user_id     BIGINT,
    person_id   INT NOT NULL,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (custom_id, user_id),
    UNIQUE (custom_id, person_id)
);

-- One row per game of the evening. lolamis_game_id NULL with a winner = recorded here but not
-- yet in lol-amis (it was down) — /custom corriger retries.
CREATE TABLE IF NOT EXISTS custom_games (
    custom_id        BIGINT NOT NULL REFERENCES customs (id) ON DELETE CASCADE,
    number           INT NOT NULL,
    teams            JSONB NOT NULL,
    winner           TEXT CHECK (winner IN ('blue', 'red')),
    lolamis_game_id  INT,
    PRIMARY KEY (custom_id, number)
);
